:root {
  color-scheme: light;
  --bg: #f6f3ee;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #e7e0d6;
  --card: #fffdf9;
  --accent: #9a3412;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.5 Georgia, "Times New Roman", serif;
}

a {
  color: inherit;
}

main {
  max-width: 720px;
  margin: 0 auto;
  padding: 48px 20px 80px;
}

h1,
h2 {
  font-weight: 600;
  letter-spacing: -0.02em;
}

h1 {
  margin: 0 0 8px;
  font-size: 2rem;
}

h2 {
  margin: 32px 0 12px;
  font-size: 1.15rem;
}

.lede {
  margin: 0 0 28px;
  color: var(--muted);
}

.list {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.card,
.form,
.empty {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.card {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  padding: 14px 16px;
}

.card a {
  text-decoration: none;
}

.card a:hover {
  text-decoration: underline;
}

.meta,
.empty,
label span,
.back {
  color: var(--muted);
}

.empty {
  padding: 14px 16px;
}

.form {
  display: grid;
  gap: 12px;
  padding: 16px;
}

label {
  display: grid;
  gap: 4px;
}

input,
textarea,
button {
  font: inherit;
}

input,
textarea {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
}

button,
.button {
  justify-self: start;
  border: 0;
  border-radius: 999px;
  padding: 8px 14px;
  background: var(--accent);
  color: white;
  cursor: pointer;
  text-decoration: none;
}

.back {
  display: inline-block;
  margin-bottom: 16px;
}

.notes {
  white-space: pre-wrap;
}

