import { getBooks } from "../lib/books";
import { createBook, markFinished } from "./actions";

export const dynamic = "force-dynamic";

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <main>
      <h1>Reading list</h1>
      <p className="lede">What you are reading, and what you have finished.</p>

      <h2>Currently reading</h2>
      <BookList books={reading} empty="Nothing in progress." showFinish />

      <h2>Finished</h2>
      <BookList books={finished} empty="No finished books yet." />

      <h2>Add a book</h2>
      <form className="form" action={createBook}>
        <label>
          <span>Title</span>
          <input name="title" required />
        </label>
        <label>
          <span>Author</span>
          <input name="author" required />
        </label>
        <label>
          <span>Notes</span>
          <textarea name="notes" rows={4} />
        </label>
        <button type="submit">Add book</button>
      </form>
    </main>
  );
}

function BookList({ books, empty, showFinish = false }) {
  if (books.length === 0) return <p className="empty">{empty}</p>;

  return (
    <ul className="list">
      {books.map((book) => (
        <li className="card" key={book.id}>
          <div>
            <a href={`/books/${book.id}`}>{book.title}</a>
            <div className="meta">{book.author}</div>
          </div>
          {showFinish ? (
            <form action={markFinished}>
              <input type="hidden" name="id" value={book.id} />
              <button type="submit">Mark finished</button>
            </form>
          ) : null}
        </li>
      ))}
    </ul>
  );
}

